<?php
namespace App\Modules\Customer\Application\UseCases;
use App\Modules\Auth\Domain\Contracts\AuthenticationServiceInterface;use App\Modules\Auth\Domain\Exceptions\AuthenticationException;use App\Modules\Customer\Domain\Contracts\CustomerFeaturesRepositoryInterface;use App\Modules\Customer\Domain\Exceptions\CustomerFeatureNotFoundException;
final class ManageCustomerNotifications {public function __construct(private readonly AuthenticationServiceInterface $auth,private readonly CustomerFeaturesRepositoryInterface $repo){}private function id():int{$u=$this->auth->user();if(!$u)throw new AuthenticationException('Unauthenticated.');return $u->id;}public function list():iterable{return $this->repo->notifications($this->id());}public function read(int $id){try{return $this->repo->markNotificationRead($this->id(),$id);}catch(\Illuminate\Database\Eloquent\ModelNotFoundException){throw new CustomerFeatureNotFoundException('Notification',$id);}} }
